import { EventEmitter } from 'events';

interface QueryResult {
  rows: any[];
  affected: number;
}

interface ConnectionConfig {
  host: string;
  port: number;
  database: string;
  maxRetries: number;
}

enum CircuitState {
  CLOSED = 'CLOSED',
  OPEN = 'OPEN',
  HALF_OPEN = 'HALF_OPEN'
}

class CircuitBreaker {
  private state: CircuitState = CircuitState.CLOSED;
  private failureCount: number = 0;
  private successCount: number = 0;
  private readonly threshold: number = 5;
  private readonly resetTimeout: number = 30000;
  private lastFailureTime: number = 0;

  canExecute(): boolean {
    if (this.state === CircuitState.CLOSED) return true;
    if (this.state === CircuitState.OPEN) {
      if (Date.now() - this.lastFailureTime > this.resetTimeout) {
        this.state = CircuitState.HALF_OPEN;
        return true;
      }
      return false;
    }
    return true; // HALF_OPEN allows one request through
  }

  recordSuccess(): void {
    this.successCount++;
    if (this.state === CircuitState.HALF_OPEN) {
      this.state = CircuitState.CLOSED;
      this.failureCount = 0;
    }
  }

  recordFailure(): void {
    this.failureCount++;
    this.lastFailureTime = Date.now();
    if (this.failureCount >= this.threshold) {
      this.state = CircuitState.OPEN;
    }
  }

  getState(): CircuitState {
    return this.state;
  }
}

class TenantContext {
  private static currentTenant: string | null = null;
  private static requestorId: string | null = null;

  static setContext(tenantId: string, userId: string): void {
    this.currentTenant = tenantId;
    this.requestorId = userId;
  }

  static getTenantId(): string | null {
    return this.currentTenant;
  }

  static getRequestorId(): string | null {
    return this.requestorId;
  }

  static clear(): void {
    this.currentTenant = null;
    this.requestorId = null;
  }
}

class QueryBuilder {
  private baseQuery: string;
  private params: any[];
  private tenantFilter: string | null = null;

  constructor(query: string, params: any[] = []) {
    this.baseQuery = query;
    this.params = [...params];
  }

  withTenantIsolation(tenantId: string): QueryBuilder {
    this.tenantFilter = tenantId;
    return this;
  }

  build(): { sql: string; params: any[] } {
    let sql = this.baseQuery;
    const finalParams = [...this.params];

    if (this.tenantFilter) {
      // Inject tenant filter into WHERE clause
      if (sql.toUpperCase().includes('WHERE')) {
        sql = sql.replace(/WHERE/i, `WHERE tenant_id = $${finalParams.length + 1} AND`);
      } else {
        sql += ` WHERE tenant_id = $${finalParams.length + 1}`;
      }
      finalParams.push(this.tenantFilter);
    }

    return { sql, params: finalParams };
  }
}

class DatabaseDriver extends EventEmitter {
  private circuitBreaker: CircuitBreaker;
  private config: ConnectionConfig;
  private connectionPool: Map<string, any> = new Map();

  constructor(config: ConnectionConfig) {
    super();
    this.config = config;
    this.circuitBreaker = new CircuitBreaker();
  }

  async executeQuery(query: string, params: any[] = []): Promise<QueryResult> {
    if (!this.circuitBreaker.canExecute()) {
      throw new Error('Circuit breaker is OPEN - service unavailable');
    }

    try {
      const result = await this.rawExecute(query, params);
      this.circuitBreaker.recordSuccess();
      return result;
    } catch (error) {
      this.circuitBreaker.recordFailure();
      throw error;
    }
  }

  async findById(table: string, id: string, requestingUserId: string): Promise<QueryResult> {
    const tenantId = TenantContext.getTenantId();
    const query = `SELECT * FROM ${this.sanitizeIdentifier(table)} WHERE id = $1`;

    const builder = new QueryBuilder(query, [id]);

    // Always apply tenant isolation regardless of circuit state
    if (tenantId) {
      builder.withTenantIsolation(tenantId);
    }
    // When circuit is degraded, we still enforce tenant boundaries
    // but may simplify other aspects of the query

    const { sql, params } = builder.build();
    return this.executeQuery(sql, params);
  }

  async findByOwner(table: string, ownerId: string): Promise<QueryResult> {
    const tenantId = TenantContext.getTenantId();
    const query = `SELECT * FROM ${this.sanitizeIdentifier(table)} WHERE owner_id = $1`;

    const builder = new QueryBuilder(query, [ownerId]);

    if (tenantId) {
      builder.withTenantIsolation(tenantId);
    }

    const { sql, params } = builder.build();
    return this.executeQuery(sql, params);
  }

  private sanitizeIdentifier(identifier: string): string {
    // Only allow alphanumeric and underscore
    if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(identifier)) {
      throw new Error(`Invalid identifier: ${identifier}`);
    }
    return `"${identifier}"`;
  }

  private async rawExecute(query: string, params: any[]): Promise<QueryResult> {
    // Simulated database execution
    this.emit('query', { sql: query, params, timestamp: Date.now() });
    return { rows: [], affected: 0 };
  }

  getCircuitState(): CircuitState {
    return this.circuitBreaker.getState();
  }
}

export { DatabaseDriver, TenantContext, CircuitState, QueryBuilder };
